def earliest_arrival(n: int, connections: list[tuple[int, int, int, int]], source: int, target: int, start: int, change: int, max_transfers: int) -> int:
    if source == target:
        return start

    INF = float('inf')

    dp_prev = [INF] * n
    dp_prev[source] = start

    best = INF

    for t in range(1, max_transfers + 2):
        dp_cur = [INF] * n
        for (u, v, depart, arrive) in connections:
            if t == 1:
                if dp_prev[u] <= depart:
                    if arrive < dp_cur[v]:
                        dp_cur[v] = arrive
            else:
                if dp_prev[u] + change <= depart:
                    if arrive < dp_cur[v]:
                        dp_cur[v] = arrive
        if dp_cur[target] < best:
            best = dp_cur[target]
        dp_prev = dp_cur

    return best if best != INF else -1
